import { Effect, Data } from 'effect';

// Use Data.TaggedError for ergonomic tagged errors
class NotFoundError extends Data.TaggedError('NotFoundError')<{
  readonly id: number;
}> {}

class ValidationError extends Data.TaggedError('ValidationError')<{
  readonly field: string;
  readonly message: string;
}> {}

const findUser = (id: number): Effect.Effect<string, NotFoundError | ValidationError> =>
  id <= 0
    ? Effect.fail(new ValidationError({ field: 'id', message: 'Must be positive' }))
    : id === 999
    ? Effect.fail(new NotFoundError({ id }))
    : Effect.succeed(`User${id}`);

const program = findUser(42).pipe(
  Effect.catchTag('NotFoundError', err =>
    Effect.succeed(`No user with id ${err.id}`)
  ),
  Effect.catchTag('ValidationError', err =>
    Effect.fail(new Error(`Invalid: ${err.field} - ${err.message}`))
  )
);

Effect.runPromise(program).then(console.log);

import { Effect, Layer, Context } from 'effect';

