const LoggerLive = Layer.succeed(Logger, { log: (msg) => Effect.sync(() => console.log(msg)) });

// Combine layers and provide to program
const AppLayer = Layer.merge(UserRepoLive, LoggerLive);

// Now R becomes never and Effect.runPromise accepts it
Effect.runPromise(program.pipe(Effect.provide(AppLayer)));

