import { Effect } from 'effect';

// Effect.promise: for Promises that NEVER reject (e.g., setTimeout)
// If they do reject, Effect treats it as a defect (unexpected)
const sleep = (ms: number) =>
  Effect.promise(() => new Promise<void>(resolve => setTimeout(resolve, ms)));

// Effect.tryPromise: for Promises that might reject (HTTP, DB, etc.)
// Maps rejection to a typed error in the E channel
const fetchUser = (id: number) =>
  Effect.tryPromise({
    try: () => fetch(`/api/users/${id}`).then(res => {
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return res.json();
    }),
    catch: (err) => new Error(`Fetch failed: ${String(err)}`)
  });
// Type: Effect<any, Error, never>

const program = Effect.gen(function*() {
  yield* sleep(100); // Promise that won't reject
  const user = yield* fetchUser(1); // Promise that might reject
  return user;
});

Effect.runPromise(program).then(console.log);

