import { Redis } from '@upstash/redis';

const redis = Redis.fromEnv();

async function transferFunds(fromKey: string, toKey: string, amount: number) {
  // redis.multi() creates an atomic transaction (MULTI/EXEC)
  const tx = redis.multi();

  tx.decrby(fromKey, amount);
  tx.incrby(toKey, amount);

  // All commands execute atomically
  const [fromBalance, toBalance] = await tx.exec<[number, number]>();

  console.log(`From: ${fromBalance}, To: ${toBalance}`);
  return { fromBalance, toBalance };
}

transferFunds('account:alice', 'account:bob', 50);

