}

async function createSession(sessionId: string, userId: string) {
  const session: Session = {
    userId,
    createdAt: Date.now(),
  };

  // Set with expiry in a single command
  await redis.set(`session:${sessionId}`, session, {
    ex: 3600, // seconds (1 hour)
    // px: 3600000, // milliseconds alternative
    // exat: Math.floor(Date.now() / 1000) + 3600, // Unix timestamp alternative
  });

