export function NestedDialog({ onParentClose }) {
  const [open, setOpen] = React.useState(false);

  return (
    <Dialog.Root open={open} onOpenChange={setOpen}>
      <Dialog.Trigger>Open Inner Dialog</Dialog.Trigger>
      <Dialog.Portal>
        <Dialog.Overlay />
        <Dialog.Content
          // Prevent Escape from bubbling to parent component
          onEscapeKeyDown={(event) => {
            event.preventDefault(); // prevent default close
            event.stopPropagation(); // stop bubbling to parent
            setOpen(false); // manually close this dialog
          }}
        >
          <Dialog.Title>Inner Dialog</Dialog.Title>
          <Dialog.Close>Close</Dialog.Close>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

